window.CKAudio=(()=>{let ctx=null,enabled=false;return{get enabled(){return enabled;},async enable(){try{ctx=ctx||new(window.AudioContext||window.webkitAudioContext)();await ctx.resume();enabled=ctx.state==='running';return enabled;}catch(e){enabled=false;return false;}},mute(){enabled=false;if(ctx)ctx.suspend().catch(()=>{});},play(kind='tap'){if(!enabled||!ctx||document.hidden||ctx.state!=='running')return;const osc=ctx.createOscillator(),gain=ctx.createGain();osc.type='sine';osc.frequency.setValueAtTime(kind==='unlock'?660:kind==='phone'?880:440,ctx.currentTime);osc.frequency.exponentialRampToValueAtTime(kind==='unlock'?880:330,ctx.currentTime+.15);gain.gain.setValueAtTime(.0001,ctx.currentTime);gain.gain.exponentialRampToValueAtTime(.035,ctx.currentTime+.01);gain.gain.exponentialRampToValueAtTime(.0001,ctx.currentTime+.22);osc.connect(gain);gain.connect(ctx.destination);osc.start();osc.stop(ctx.currentTime+.23);}};})();
